<!--
 * 流程模板（列表页）
 *
 * @path apps\workflow-web\src\views\template\index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 流程模板（列表页）
 * <p>消费后端契约 FlowTemplateController（src/api/flowTemplate.ts，auto-generated by bash/gen-contract.py）：
 * 列表 listTemplates()（非分页，query 直接返回 { items, total: items.length }），
 * 支持导入 importTemplate、克隆 cloneTemplate、新建版本 createNewVersion、
 * 版本历史 listTemplateVersions 抽屉（getTemplateVersion 查看详情）。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeGridProps } from '@ydsz/plugins/vxe-table';
import { Page, useYDSZModal } from '@ydsz/common-ui';
import { ElButton, ElDrawer, ElMessage, ElMessageBox, ElTable, ElTableColumn } from 'element-plus';
import { h, ref } from 'vue';
import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import {
  cloneTemplate,
  createNewVersion,
  getTemplateVersion,
  importTemplate,
  listTemplates,
  listTemplateVersions,
} from '#/api/flowTemplate';
import TemplateForm from './template-form.vue';

defineOptions({ name: 'TemplateManagement' });

/** 行类型：后端契约未声明模板 VO，使用 Record<string, unknown> 兼容（可选链收窄取值） */
type TemplateRow = Record<string, unknown>;

/** 安全读取字符串字段 */
function str(row: TemplateRow, key: string): string {
  const value = row[key];
  return typeof value === 'string' ? value : '';
}

/** 安全读取数字字段 */
function num(row: TemplateRow, key: string): number {
  const value = row[key];
  return typeof value === 'number' ? value : 0;
}

const gridOptions: VxeGridProps<TemplateRow> = {
  columns: [
    { type: 'seq', width: 50, title: '序号' },
    { field: 'templateCode', title: '模板编码', width: 150 },
    { field: 'templateName', title: '模板名称', width: 200 },
    { field: 'category', title: '分类', width: 100 },
    { field: 'version', title: '版本', width: 80 },
    { field: 'status', title: '状态', width: 80 },
    { field: 'updatedAt', title: '更新时间', width: 170 },
    {
      field: 'action', title: '操作', width: 220, fixed: 'right',
      slots: {
        default: ({ row }) =>
          h('div', { class: 'flex gap-1' }, [
            h(ElButton, { size: 'small', link: true, type: 'primary', onClick: () => handleImport(row) }, () => '导入'),
            h(ElButton, { size: 'small', link: true, type: 'primary', onClick: () => handleClone(row) }, () => '克隆'),
            h(ElButton, { size: 'small', link: true, type: 'primary', onClick: () => handleNewVersion(row) }, () => '新建版本'),
            h(ElButton, { size: 'small', link: true, type: 'primary', onClick: () => openVersions(row) }, () => '版本'),
          ]),
      },
    },
  ],
  height: 'auto',
  pagerConfig: { pageSize: 20, pageSizes: [10, 20, 50, 100] },
  proxyConfig: {
    ajax: {
      // listTemplates() 为全量非分页接口：直接返回全部条目，total 取条目数
      query: async (_params, formValues) => {
        const values = (formValues ?? {}) as TemplateRow;
        const items = (await listTemplates({ category: str(values, 'category') || undefined })) ?? [];
        return { items, total: items.length };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, zoom: true },
  formConfig: {
    enabled: true,
    items: [
      { field: 'category', title: '分类', itemRender: { name: 'Input', props: { placeholder: '分类' } } },
    ],
  },
};

const [Grid, gridApi] = useYDSZVxeGrid({ gridOptions });
const [TemplateFormModal, templateFormApi] = useYDSZModal({ connectedComponent: TemplateForm });

/** 模板编码获取失败时的统一提示 */
function getTemplateCode(row: TemplateRow): string | undefined {
  const code = str(row, 'templateCode');
  if (!code) {
    ElMessage.warning('该模板缺少 templateCode，无法操作');
    return undefined;
  }
  return code;
}

/** 导入模板（可填写流程名称） */
async function handleImport(row: TemplateRow) {
  const templateCode = getTemplateCode(row);
  if (!templateCode) return;
  try {
    const { value: flowName } = await ElMessageBox.prompt('请输入导入后的流程名称（可选）', '导入模板', {
      inputPlaceholder: 'flowName',
      inputValidator: (value) => (value ? true : '流程名称不能为空'),
    });
    await importTemplate({ templateCode }, { flowName });
    ElMessage.success('导入成功');
    gridApi.query();
  } catch {
    // 用户取消或请求失败
  }
}

/** 克隆模板（可填写新模板名称） */
async function handleClone(row: TemplateRow) {
  const templateCode = getTemplateCode(row);
  if (!templateCode) return;
  try {
    const { value: newTemplateName } = await ElMessageBox.prompt('请输入新模板名称', '克隆模板', {
      inputPlaceholder: 'newTemplateName',
      inputValidator: (value) => (value ? true : '新模板名称不能为空'),
    });
    await cloneTemplate({ templateCode }, { newTemplateName });
    ElMessage.success('克隆成功');
    gridApi.query();
  } catch {
    // 用户取消或请求失败
  }
}

/** 基于现有模板创建新版本 */
async function handleNewVersion(row: TemplateRow) {
  const templateCode = getTemplateCode(row);
  if (!templateCode) return;
  try {
    const { value: versionLabel } = await ElMessageBox.prompt('请输入版本标签（可选）', '新建版本', {
      inputPlaceholder: 'versionLabel（如 v2.0）',
    });
    await createNewVersion({ templateCode }, { versionLabel: versionLabel || undefined });
    ElMessage.success('已创建新版本');
    gridApi.query();
  } catch {
    // 用户取消或请求失败
  }
}

/** 版本历史抽屉状态 */
const versionsVisible = ref(false);
const versionsLoading = ref(false);
const versionRows = ref<TemplateRow[]>([]);
const currentTemplateCode = ref('');

/** 打开版本历史抽屉 */
async function openVersions(row: TemplateRow) {
  const templateCode = getTemplateCode(row);
  if (!templateCode) return;
  currentTemplateCode.value = templateCode;
  versionsVisible.value = true;
  await loadVersions();
}

/** 加载当前模板的版本列表 */
async function loadVersions() {
  if (!currentTemplateCode.value) return;
  versionsLoading.value = true;
  try {
    versionRows.value = (await listTemplateVersions({ templateCode: currentTemplateCode.value })) ?? [];
  } finally {
    versionsLoading.value = false;
  }
}

/** 查看版本详情（getTemplateVersion，响应结构未知，以格式化 JSON 展示） */
async function handleVersionDetail(versionItem: TemplateRow) {
  if (!currentTemplateCode.value) return;
  const version = num(versionItem, 'version') || Number(str(versionItem, 'version'));
  if (!version && !str(versionItem, 'version')) {
    ElMessage.warning('该版本缺少 version 信息');
    return;
  }
  try {
    const detail = await getTemplateVersion({ templateCode: currentTemplateCode.value, version });
    ElMessageBox.alert(`<pre class="text-left text-xs max-h-64 overflow-auto">${JSON.stringify(detail, null, 2)}</pre>`, `版本详情 ${version}`, {
      dangerouslyUseHTMLString: true,
    });
  } catch {
    // 请求失败提示由拦截器统一处理
  }
}
</script>
<template>
  <Page auto-content-height>
    <Grid table-title="流程模板">
      <template #toolbar-tools>
        <ElButton type="primary" @click="templateFormApi.open()">模板导入</ElButton>
      </template>
    </Grid>
    <TemplateFormModal @success="gridApi.query()" />
    <ElDrawer v-model="versionsVisible" title="模板版本历史" :size="540">
      <div class="mb-2 flex justify-end">
        <ElButton size="small" @click="loadVersions">刷新</ElButton>
      </div>
      <ElTable :data="versionRows" border size="small" v-loading="versionsLoading">
        <ElTableColumn prop="version" label="版本" width="90" />
        <ElTableColumn prop="versionLabel" label="版本标签" width="120" />
        <ElTableColumn prop="templateName" label="模板名称" min-width="120" show-overflow-tooltip />
        <ElTableColumn prop="status" label="状态" width="90" />
        <ElTableColumn prop="updatedAt" label="更新时间" width="170" />
        <ElTableColumn label="操作" width="90" fixed="right">
          <template #default="{ row }">
            <ElButton link type="primary" size="small" @click="handleVersionDetail(row as TemplateRow)">查看</ElButton>
          </template>
        </ElTableColumn>
      </ElTable>
    </ElDrawer>
  </Page>
</template>